// Response shapes of the FastAPI backend (camelCase; money = minor units as strings).
// Sprint 2: replace with types generated by `pnpm api:types` (openapi-typescript).

export type Currency = "NGN" | "USD" | "GBP" | "EUR" | "CAD" | "AUD" | "KES";
export type NeedCategory =
  | "MEDICAL"
  | "EDUCATION"
  | "HOUSING"
  | "FOOD_UPKEEP"
  | "TRANSPORT"
  | "MINISTRY_EQUIPMENT"
  | "OUTREACH"
  | "EMERGENCY"
  | "FAMILY_WELFARE"
  | "OTHER";
export type NeedStatus =
  | "OPEN"
  | "PARTIALLY_FUNDED"
  | "FUNDED"
  | "DISBURSED"
  | "FULFILLED"
  | "EXPIRED";
export type NeedUrgency = "NORMAL" | "URGENT" | "CRITICAL";
export type PrayerHub = "SYDNEY" | "LAGOS" | "NEW_YORK" | "VANCOUVER";

export interface Region {
  name: string;
  slug: string;
}

export interface NeedCard {
  code: string;
  slug: string;
  title: string;
  summary: string;
  category: NeedCategory;
  urgency: NeedUrgency;
  region: Region;
  missionary: {
    publicName: string;
    slug: string;
    isSensitive: boolean;
    publicLocation: string | null;
  } | null;
  targetMinor: string;
  raisedMinor: string;
  availableMinor: string;
  currency: Currency;
  percent: number;
  contributorCount: number;
  deadlineAt: string | null;
  status: NeedStatus;
  coverImage: string | null;
}

export interface NeedDetail extends NeedCard {
  story: string;
  updates: { title: string; body: string; isFinal: boolean; createdAt: string }[];
}

export interface Page<T> {
  data: T[];
  meta: { page: number; pageSize: number; total: number };
}

export interface ImpactStats {
  missionariesSupported: number;
  needsMetThisYear: number;
  needsTotalThisYear: number;
  prayerHoursCovered: number;
  territories: number;
}

export interface PrayerHubConfig {
  hub: PrayerHub;
  displayName: string;
  timezone: string;
  watchStartUtc: number;
  watchEndUtc: number;
}

export interface CoverageCell {
  weekdayUtc: number;
  hourUtc: number;
  count: number;
}

export interface WatchSummary {
  slug: string;
  title: string;
  description: string | null;
  bannerImage: string | null;
  startsAt: string;
  endsAt: string;
  roundCount: number;
  signupCount: number;
}

export interface WatchSlot {
  id: string;
  startsAt: string;
  endsAt: string;
  capacity: number | null;
  taken: number;
  isFull: boolean;
}

export interface WatchDetail extends WatchSummary {
  rounds: { id: string; label: string; isRequired: boolean; slots: WatchSlot[] }[];
}

export interface WatchSignupResult {
  watchTitle: string;
  slots: { roundLabel: string; startsAt: string; endsAt: string }[];
  meetingUrl: string | null;
}

export interface Problem {
  type: string;
  title: string;
  status: number;
  detail?: string;
  [key: string]: unknown;
}
